#include <iostream>

struct Rectangle {
    int width;
    int height;
};

int area(Rectangle r) {
    return r.width * r.height;
}

int main() {
    int n;
    std::cin >> n;
    int total = 0;
    for (int i = 0; i < n; ++i) {
        int w, h;
        std::cin >> w >> h;
        Rectangle r;
        r.width = w;
        r.height = h;
        int a = area(r);
        total += a;
        std::cout << "Area: " << a << "\n";
    }
    std::cout << "Total: " << total << "\n";
    return 0;
}

