solution_code:
#include <iostream>
#include <cstdlib>

struct Point {
    int x;
    int y;
};

int manhattan(Point a, Point b) {
    return std::abs(a.x - b.x) + std::abs(a.y - b.y);
}

int main() {
    int n;
    std::cin >> n;
    Point prev;
    std::cin >> prev.x >> prev.y;
    int total = 0;
    for (int i = 1; i < n; ++i) {
        Point cur;
        std::cin >> cur.x >> cur.y;
        int d = manhattan(prev, cur);
        total += d;
        std::cout << "Step: " << d << "\n";
        prev = cur;
    }
    std::cout << "Total: " << total << "\n";
    return 0;
}
